package com.yeyamo_mobile.api.commerce_service.config;
import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.web.builders.*;import org.springframework.security.web.*;
@Configuration public class SecurityConfig{@Bean SecurityFilterChain chain(HttpSecurity http)throws Exception{return http.csrf(csrf->csrf.disable()).authorizeHttpRequests(auth->auth.requestMatchers("/actuator/health").permitAll().requestMatchers("/api/v1/commerce/admin/**").hasAnyRole("ADMIN","SUPER_ADMIN").anyRequest().authenticated()).oauth2ResourceServer(oauth->oauth.jwt(jwt->{})).build();}}
